// Validate required fields
const body = $input.item.json.body;
const required = ['vehicle_id', 'timestamp_utc', 'lat', 'lon', 'alt_ft_agl', 'speed_kmh', 'battery_pct'];
for (const f of required) {
  if (body[f] === undefined) throw new Error(`Missing field: ${f}`);
}

// Normalize altitude to both AGL and MSL
const ALT_OFFSET = { 'LA': 370 }; // ft MSL offset for metro
const metro = 'LA';

return [{
  json: {
    vehicle_id: body.vehicle_id,
    timestamp_utc: body.timestamp_utc,
    race_id: $env.MRCP_RACE_ID,
    position: { lat: body.lat, lon: body.lon, alt_ft_agl: body.alt_ft_agl, alt_ft_msl: body.alt_ft_agl + (ALT_OFFSET[metro] || 0) },
    speed_kmh: body.speed_kmh,
    battery_pct: body.battery_pct,
    health_status: body.health_status || 'OK',
    abort_status: body.abort_status || false,
    ingest_ts: Date.now()
  }
}];
